+    const rules = await resolveRules("eslint.config.mjs");
+    const missing = Object.keys(editorRules).filter(
+      (rule) => rules[rule] === undefined || severityOf(rules[rule]) === 0,
+    );
+    expect(missing).toEqual([]);
+  });
